/// A Slice kind with configuration or parameters supplied through Context.
///
/// This enum is the allowlist of Slice behavior supported by the simulation.
/// A kind may be directly enabled by the user or invoked for an instance
/// generated by another Slice. Internal calculations without their own
/// Context settings are not included.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum SliceKind {
    /// Calculates loan activity configured for the simulation.
    Loan,

    /// Calculates recurring fixed property-related expenses.
    FixedExpense,

    /// Calculates rental income configured for the simulation.
    Rental,

    /// Determines recurring repair occurrences.
    RepairOccurrence,

    /// Calculates the cost of a repair instance, including instances
    /// generated by a repair occurrence.
    RepairCost,
}
